def solve(inputs: dict) -> float:
    x = int(inputs['X']) & 0xFFFFFFFF
    a = int(inputs['A']); b = int(inputs['B']); c = int(inputs['C']); k = int(inputs['K'])
    for _ in range(k):
        x ^= (x << a) & 0xFFFFFFFF
        x ^= (x >> b) & 0xFFFFFFFF
        x ^= (x << c) & 0xFFFFFFFF
        x &= 0xFFFFFFFF
    return float(x)

